-- Real photos for the Stuttgart Nation Clash gold and silver medals (also called the Europe National Clash). Bronze keeps its current picture. Add the Korean Jinx launch card. Safe to run more than once.
update promo_items set data = data || $j${"img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/rc-stuttgart-nation-clash-medal-gold.webp", "inf": "Nation Clash side event at the Regional Championship Europe in Stuttgart (November 2026), also known as the Europe National Clash. The top three individual point earners per country each receive a medal (gold, silver, bronze). This is the gold medal.", "tg": "Medal\nNation Clash\nEurope National Clash\nRegional Championship\nGold"}$j$::jsonb where id = 'item-10339';
update promo_items set data = data || $j${"img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/rc-stuttgart-nation-clash-medal-silver.webp", "inf": "Nation Clash side event at the Regional Championship Europe in Stuttgart (November 2026), also known as the Europe National Clash. The top three individual point earners per country each receive a medal (gold, silver, bronze). This is the silver medal.", "tg": "Medal\nNation Clash\nEurope National Clash\nRegional Championship\nSilver"}$j$::jsonb where id = 'item-10340';
update promo_items set data = data || $j${"inf": "Nation Clash side event at the Regional Championship Europe in Stuttgart (November 2026), also known as the Europe National Clash. The top three individual point earners per country each receive a medal (gold, silver, bronze). This is the bronze medal.", "tg": "Medal\nNation Clash\nEurope National Clash\nRegional Championship\nBronze"}$j$::jsonb where id = 'item-10341';
insert into promo_items (id, r, data)
select 'item-10662', 10662, $j${"r": 10662, "id": "item-10662", "cat": "PROMO", "nm": "Jinx, Demolitionist [Korea Launch Exclusive]", "la": "Korean", "ev": "Korea Launch - Gen.G GGX, Seoul\nKorea Launch - Yongsan IPark Dopamine Station, Seoul", "se": "OGN", "ty": "Card", "cn": "030", "ra": "Promo", "do": "Fury", "tg": "Champion Unit\nJinx\nZaun\nKorea Exclusive\nLaunch Stamp", "fo": true, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": "Clear plastic bag (sealed)", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/jinx-demolitionist-korea-launch-kr-item-10662.webp", "inf": "Korea-exclusive Jinx promo (OGN 030/298 P KR) with the Korean launch stamp (출시 특별판, \"launch special edition\"), handed out at the Korean launch events in Seoul in September 2026: Gen.G GGX (Sept 18 to 23) and Yongsan IPark Dopamine Station (Sept 18 to 30). Riot lists it as one of two promos available through the Korean launch events."}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10662');
